class KeyButton {
	constructor(inLet, inx, iny, inSize, inPt) {
		this.letter = inLet;
		this.x = inx;
		this.y = iny;
		this.w = inSize;
		this.h = inSize;
		this.txtPt = inPt;
		this.faded = false;
		this.fadeLevel = 0;
	}

	render(offsetx, offsety) {
		noStroke();
		fill('black');
		rect(this.x + offsetx, this.y + offsety + 4, this.w, this.h, 10);
		fill('gray');
		rect(this.x + offsetx, this.y + offsety, this.w, this.h, 10);
		if (this.faded){
			if (this.fadeLevel < 255){
				this.fadeLevel++;
			}
			fill(color(0,0,0,255 - this.fadeLevel));
		}else{
			fill('black');
		}
		textSize(this.txtPt);
		let centerLet = this.w * 0.5;
		text(this.letter, this.x + offsetx + centerLet, this.y + offsety + centerLet + 20);
	}


}

