class LetterTween {
	constructor(inLetA, inLetB, steps) {
		this.totalSteps = steps;
		this.allPtsA = this.getPointsCharacter(inLetA);
		this.allPtsB = this.getPointsCharacter(inLetB);
		let bodyObjA = this.idContours(this.allPtsA);
		let bodyObjB = this.idContours(this.allPtsB);
		this.bodyTween = this.getTweenShapes(bodyObjA.bodyPoints, bodyObjB.bodyPoints, steps);
		this.hasContours = false;
		let numContoursA = bodyObjA.contours.length;
		let numContoursB = bodyObjB.contours.length;
		if (numContoursA != numContoursB) {
			let numMissing = abs(numContoursA - numContoursB);
			let missingA = true;
			if (numContoursA > numContoursB) {
				missingA = false;
			}
			//if one shape has less contours, create a placeholder shape so it can morph contour set
			//here the placeholder is three points at center of other letter's contour, when morphing looks like it expands/shrinks to contour shape
			let placeholderC = [];
			for (let i = 0; i < numMissing; i++) {
				if (missingA) {
					let csetB = bodyObjB.contours[numContoursB - 1 - i];
					let ptCenter = this.getPointSetCenter(csetB);
					let csetA = [ptCenter, ptCenter, ptCenter];
					placeholderC.push(csetA);
				} else {
					let csetA = bodyObjA.contours[numContoursA - 1 - i];
					let ptCenter = this.getPointSetCenter(csetA);
					let csetB = [ptCenter, ptCenter, ptCenter];
					placeholderC.push(csetB);
				}
			}

			for (let i = 0; i < placeholderC.length; i++) {
				if (missingA) {
					bodyObjA.contours.push(placeholderC[i]);
				} else {
					bodyObjB.contours.push(placeholderC[i]);
				}
			}

		}
		numContoursA = bodyObjA.contours.length;
		numContoursB = bodyObjB.contours.length;
		let useC = min(numContoursA, numContoursB);
		if (useC > 0) {
			this.hasContours = true;
			this.contourTweens = [];
			for (let i = 0; i < useC; i++) {
				this.contourTweens.push(this.getTweenShapes(bodyObjA.contours[i], bodyObjB.contours[i], steps));
			}
		}

	}

	renderTweenAtTV(tv) {
		//drawing contours does not seem to work correctly 
		let atStep = floor(tv * this.totalSteps);
		let bodyAtStep = this.bodyTween[atStep];
		beginShape();
		for (let i = 0; i < bodyAtStep.length; i++) {
			let tpt = bodyAtStep[i];
			vertex(tpt.x, tpt.y);
		}
		if (this.contourTweens != null) {
			for (let c = 0; c < this.contourTweens.length; c++) {
				let tcontween = this.contourTweens[c];
				beginContour();
				for (let p = tcontween.length - 1; p >= 0; p--) {
					let cpt = tcontween[p];
					vertex(cpt.x, cpt.y);
				}
				endContour();
			}
		}
		endShape();
	}

	fullRender(colFG, colBG, tv) {
		//this render mode draws shape in foreground color and internal contours are drawn over it in background color
		fill(colFG);
		this.renderBodySolo(tv);
		if (this.hasContours) {
			fill(colBG);
			this.renderContoursSolo(tv);
		}

	}

	renderBodySolo(tv) {
		//just render the letter's outline (body shape)
		let atStep = floor(tv * this.totalSteps);
		let bodyAtStep = this.bodyTween[atStep];
		beginShape();
		for (let i = 0; i < bodyAtStep.length; i++) {
			let tpt = bodyAtStep[i];
			vertex(tpt.x, tpt.y);
		}
		endShape();
	}

	renderContoursSolo(tv) {
		//render only the internal contour shapes
		let atStep = floor(tv * this.totalSteps);
		let contourShapes = this.contourTweens[0];
		let shapeAtStep = contourShapes[atStep];
		beginShape();
		for (let i = 0; i < shapeAtStep.length; i++) {
			let tpt = shapeAtStep[i];
			vertex(tpt.x, tpt.y);
		}
		endShape();
	}

	getPointsCharacter(inChar) {
		//let dim = height / 3.25;
		let tpts = font.textToPoints(inChar, -34, 0, 180, {
			sampleFactor: 0.2
		});
		return tpts;
	}

	getPointSetCenter(pset) {
		//get the average position of the set
		let centerx = 0;
		let centery = 0;
		for (let i = 0; i < pset.length; i++) {
			let pt = pset[i];
			centerx += pt.x;
			centery += pt.y;
		}
		centerx /= pset.length;
		centery /= pset.length;
		return {
			x: centerx,
			y: centery
		};
	}

	idContours(ptset) {
		//identify which points in the array are the main outline (the first group) and the internal contours that follow
		let lastPt = ptset[0];
		let standardDist = -1;
		let majorBody = [];
		let contours = [];
		let subContour = [];
		let ptGroup = 0;
		for (let i = 1; i < ptset.length; i++) {
			let thisPt = ptset[i];
			let ptDist = dist(thisPt.x, thisPt.y, lastPt.x, lastPt.y);
			if (standardDist < 0) {
				standardDist = ptDist;
			}
			let distDiff = abs(ptDist - standardDist);
			//this difference is going to be correct only for specific text sizes and point density
			//creates a new contour when moving more than expected
			if (distDiff > 4) {
				if (ptGroup > 0) {
					contours.push(subContour.slice());
				}
				subContour = [];
				ptGroup++;

			}
			if (ptGroup == 0) {
				majorBody.push(thisPt);
			} else {
				subContour.push(thisPt);
			}
			lastPt = thisPt;
		}
		if (ptGroup > 0) {
			let subclen = subContour.length;
			//console.log("sub c length = " + subclen);
			contours.push(subContour.slice());
		}
		let lobj = {
			bodyPoints: majorBody,
			contours: contours
		}
		return lobj;
	}

	getTweenShapes(ptsA, ptsB, numSteps){
		let nptsA = this.reorderTopLeftStart(ptsA);
		let nptsB = this.reorderTopLeftStart(ptsB);
		return this.tweenLetterShapes(nptsA, nptsB, numSteps);
	}

	reorderTopLeftStart(inArr) {
		//rearrange point order so first point is topmost-leftmost
		let topPt = null;
		let leftPt = null;
		let topMost = 100000;
		let leftMost = 100000;
		for (let i = 0; i < inArr.length; i++) {
			let inPt = inArr[i];
			if (inPt.x < leftMost) {
				leftMost = inPt.x;
				leftPt = inPt;
			}
			if (inPt.y < topMost) {
				topMost = inPt.y;
				topPt = inPt;
			}
		}
		let startPt;
		if (topPt == leftPt) {
			startPt = topPt;
		} else {
			let topY = topPt.y;
			let leftMostY = 10000;
			for (let i = 0; i < inArr.length; i++) {
				let inPt = inArr[i];
				if (inPt.y == topY) {
					if (inPt.x < leftMostY) {
						leftMostY = inPt.x;
						startPt = inPt;
					}
				}
			}
		}
		let startIndex;
		if (startPt != null) {
			startIndex = inArr.indexOf(startPt);
		} else if (topPt != null) {
			startIndex = inArr.indexOf(topPt);
		} else {
			console.log("no startPt and no topPt from inArr");
			startIndex = 0;
		}
		let reordered = [];
		for (let i = 0; i < inArr.length; i++) {
			let uidx = (startIndex + i) % inArr.length;
			reordered.push(inArr[uidx]);
		}
		return reordered;
	}

	tweenLetterShapes(fromShape, toShape, numsteps) {
		//get all of the shapes in between from and to, as an array, numsteps is how many shapes to create
		// Step 1: Resample both shapes to have the same number of points
		const pointCount = max(fromShape.length, toShape.length);
		const resampledFrom = this.resampleShape(fromShape, pointCount);
		const resampledTo = this.resampleShape(toShape, pointCount);

		// Step 2: Find the best rotational alignment to minimize movement
		const alignedShapes = this.alignShapes(resampledFrom, resampledTo);

		let allTweens = [];
		for (let i = 0; i < numsteps; i++) {

			let progress = i / numsteps;
			// Step 3: Interpolate between corresponding points
			const tweenedShape = [];
			for (let i = 0; i < alignedShapes.from.length; i++) {
				const fromPoint = alignedShapes.from[i];
				const toPoint = alignedShapes.to[i];

				tweenedShape.push({
					x: fromPoint.x + (toPoint.x - fromPoint.x) * progress,
					y: fromPoint.y + (toPoint.y - fromPoint.y) * progress
				});
			}
			allTweens.push(tweenedShape);
		}

		return allTweens;
	}

	resampleShape(shape, n) {
		// Step 1: Calculate the total arc length of the shape
		const arcLengths = [0];
		let totalLength = 0;

		for (let i = 1; i < shape.length; i++) {
			const prev = shape[i - 1];
			const curr = shape[i];
			const segmentLength = sqrt(
				pow(curr.x - prev.x, 2) +
				pow(curr.y - prev.y, 2)
			);
			totalLength += segmentLength;
			arcLengths.push(totalLength);
		}

		// Add the closing segment if the shape is closed
		const first = shape[0];
		const last = shape[shape.length - 1];
		const closingLength = sqrt(
			pow(first.x - last.x, 2) +
			pow(first.y - last.y, 2)
		);
		totalLength += closingLength;

		// Step 2: Sample n points at equal arc length intervals
		const resampledShape = [];
		const stepLength = totalLength / n;

		for (let i = 0; i < n; i++) {
			const targetLength = i * stepLength;

			// Find the segment containing this length
			let segmentIndex = 0;
			let _wG_1 = 0; while ((segmentIndex < arcLengths.length - 1 &&
				arcLengths[segmentIndex + 1] < targetLength) && ++_wG_1 < 20000) {
				segmentIndex++;
			}

			// Handle edge case for the last point
			if (segmentIndex >= arcLengths.length - 1) {
				resampledShape.push({
					x: shape[0].x,
					y: shape[0].y
				});
				continue;
			}

			// Calculate interpolation factor within the segment
			const segmentStart = arcLengths[segmentIndex];
			const segmentEnd = segmentIndex < arcLengths.length - 1 ?
				arcLengths[segmentIndex + 1] : totalLength;
			const segmentLength = segmentEnd - segmentStart;

			if (segmentLength === 0) {
				// Handle zero-length segments
				resampledShape.push({
					x: shape[segmentIndex].x,
					y: shape[segmentIndex].y
				});
			} else {
				const t = (targetLength - segmentStart) / segmentLength;

				// Interpolate between the segment endpoints
				const p0 = shape[segmentIndex];
				const p1 = segmentIndex < shape.length - 1 ?
					shape[segmentIndex + 1] : shape[0];

				resampledShape.push({
					x: p0.x + t * (p1.x - p0.x),
					y: p0.y + t * (p1.y - p0.y)
				});
			}
		}

		return resampledShape;
	}

	alignShapes(fromShape, toShape) {
		// We need to find the best starting index offset that minimizes movement
		let bestOffset = 0;
		let minDistance = Infinity;

		// Try all possible rotational alignments
		for (let offset = 0; offset < toShape.length; offset++) {
			let totalDistance = 0;

			// Calculate total distance for this alignment
			for (let i = 0; i < fromShape.length; i++) {
				const fromPoint = fromShape[i];
				const toPoint = toShape[(i + offset) % toShape.length];

				const distance = sqrt(
					pow(fromPoint.x - toPoint.x, 2) +
					pow(fromPoint.y - toPoint.y, 2)
				);

				totalDistance += distance;
			}

			// Check if this alignment is better
			if (totalDistance < minDistance) {
				minDistance = totalDistance;
				bestOffset = offset;
			}
		}

		// Create aligned shapes with the best rotational offset
		const alignedTo = [];
		for (let i = 0; i < toShape.length; i++) {
			alignedTo.push(toShape[(i + bestOffset) % toShape.length]);
		}

		return {
			from: fromShape,
			to: alignedTo
		};
	}
	findKeyPoints(shape, maxPoints) {
		if (shape.length <= maxPoints) {
			return shape;
		}

		// Use the Douglas-Peucker algorithm to simplify the shape while preserving key points
		const simplified = this.douglasPeucker(shape, 0, shape.length - 1, 1.5);

		// If we still have too many points, use uniform sampling
		if (simplified.length > maxPoints) {
			return this.resampleShape(simplified, maxPoints);
		}

		return simplified;
	}
	douglasPeucker(points, startIndex, endIndex, epsilon) {
		// Find the point with the maximum distance
		let maxDistance = 0;
		let maxIndex = 0;

		const start = points[startIndex];
		const end = points[endIndex];

		// Handle case where start and end are very close
		const lineLength = sqrt(
			pow(end.x - start.x, 2) +
			pow(end.y - start.y, 2)
		);

		if (lineLength < epsilon) {
			return [points[startIndex]];
		}

		for (let i = startIndex + 1; i < endIndex; i++) {
			const distance = this.perpendicularDistance(points[i], start, end);

			if (distance > maxDistance) {
				maxDistance = distance;
				maxIndex = i;
			}
		}

		// If max distance is greater than epsilon, recursively simplify
		if (maxDistance > epsilon) {
			const leftResults = this.douglasPeucker(points, startIndex, maxIndex, epsilon);
			const rightResults = this.douglasPeucker(points, maxIndex, endIndex, epsilon);

			// Combine the results, removing duplicate maxIndex
			return leftResults.concat(rightResults.slice(1));
		} else {
			// No point was far enough - use only endpoints
			return [points[startIndex], points[endIndex]];
		}
	}

	perpendicularDistance(point, lineStart, lineEnd) {
		const dx = lineEnd.x - lineStart.x;
		const dy = lineEnd.y - lineStart.y;

		// Handle vertical and horizontal lines specially
		if (dx === 0) {
			return abs(point.x - lineStart.x);
		}
		if (dy === 0) {
			return abs(point.y - lineStart.y);
		}

		const slope = dy / dx;
		const intercept = lineStart.y - slope * lineStart.x;

		// Distance from point to line: |Ax + By + C| / sqrt(A² + B²)
		// For a line in form y = mx + b, this becomes |mx - y + b| / sqrt(m² + 1)
		return abs(slope * point.x - point.y + intercept) / sqrt(slope * slope + 1);
	}

}

