	wrongWordInputs = [];
	solutionWhenWrong = [];
	gameOver = false;
}

function randomWord() {
	let ridx = floor(random(validWords.length));
	let rword = validWords[ridx];
	let casedword = rword.toUpperCase();
	currentLetters = [];
	for (let i = 0; i < lettersWord; i++) {
		currentLetters.push(casedword.charAt(i));
	}
	for (let i = 0; i < lettersWord; i++) {
		letterBlocks[i].letter = currentLetters[i];
	}
}

function resetWord() {
	randomWord();
	if (checkPossibility()) {

	} else {
		let foundOne = false;
		let iter = 0;
		let _wG_2 = 0; while ((!foundOne && iter < 40) && ++_wG_2 < 20000) {
			iter++;
			randomWord();
			foundOne = checkPossibility();
		}
		if (iter == 40) {
			console.log("found no word on reset");
		}
	}
	kboard.reset();
}

function draw() {
	background(100);
	if (guide != null) {
		if (guide.complete){
			guide = null;
		}else{
			guide.render();
		}

	} else {
		for (let i = 0; i < lettersWord; i++) {
			let lb = letterBlocks[i];
			if (i == activeIndex) {
				lb.activeInput = true;
			} else {
				lb.activeInput = false;
			}
			lb.renderAt(i * (lblockw + 10), 150);
		}

		fill('black');
		textSize(36);
		textAlign(LEFT);
		let atstr = "Attempts Left: " + attemptsLeft;
		text(atstr, 120, 60);
		let scstr = "Score: " + totalScore;
		text(scstr, 600, 60);
		if (badWordShow > 0) {
			badWordShow--;
			text(badWordMessage, 50, 110);
		}
		textAlign(CENTER);
		if (messageTimer > 0) {
			messageTimer--;
			if (messageTimer == 0) {
				if (resetAfterMessage) {
					resetAfterMessage = false;
					reset();
				} else if (reloadAfterMessage) {
					resetWord();
				}
			} else {
				text(currentMessage, 500, 450);
				if (gameOver) {
					showFailures();
				}
			}
		} else {
			turnTimer++;
			if (turnTimer % 100 == 0) {
				randomLetterTest();
			}
			if (turnTimer > timeLimit) {
				//out of time
				turnEnded();
			} else {
				kboard.render();
			}

		}
		if (showSolution) {
			if (lastSolution != null) {
				text(lastSolution, 100, 900);
			}

		}
	}

}

function mousePressed() {
	if (guide != null){
		guide.onClick();
	}else{
		kboard.evalClick();
	}

}

function keyPressed() {
	let inkey = String(key);
	inkey = inkey.toUpperCase();
	if (allowedLetters.includes(inkey)) {
		letterInput(inkey);
	}
}

function letterInput(inkey) {

	let iterateTurn = false;
	let letterWas = currentLetters[activeIndex];
	if (letterWas == inkey) {
		//same letter
	} else {
		iterateTurn = true;
		currentLetters[activeIndex] = inkey;
		let completeWord = getCurrentWord();
		if (checkCurrentWord(completeWord)) {
			if (useLetterMorph) {
				letterBlocks[activeIndex].setLetterMorphTo(inkey);
			} else {
				letterBlocks[activeIndex].letter = inkey;
			}

			let tscore = timeLimit - turnTimer;
			totalScore += tscore;
		} else {
			badWordMessage = "";
			badWordMessage += completeWord;
			badWordMessage += " was not in my dictionary."
			badWordShow = 180;
			wrongWordInputs.push(completeWord);
			solutionWhenWrong.push(lastSolution);
			letterBlocks[activeIndex].redFlash = 5;
			currentLetters[activeIndex] = letterWas;
			attemptsLeft--;

		}
	}

	if (attemptsLeft <= 0) {
		//reset();
		currentMessage = "Game Over!";
		messageTimer = 1000;
		resetAfterMessage = true;
		gameOver = true;
	} else if (iterateTurn) {
		turnEnded();
	}
}

function showFailures() {
	for (let i = 0; i < wrongWordInputs.length; i++) {
		let txty = 500 + (i * 50);
		let msgstr = "Your word " + wrongWordInputs[i] + " could have passed as " + solutionWhenWrong[i];
		text(msgstr, 500, txty);
	}
}

function turnEnded() {
	activeIndex++;
	activeIndex %= lettersWord;
	kboard.reset();
	turnTimer = 0;
	if (checkPossibility()) {

	} else {
		currentMessage = "No possible words found! Let me shuffle.";
		messageTimer = 100;
		reloadAfterMessage = true;
	}
}

function randomLetterTest() {
	let foundLetter = false;
	let iter = 0;
	let letter = null;
	let _wG_3 = 0; while ((!foundLetter && iter < 20) && ++_wG_3 < 20000) {
		iter++;
		let rlidx = floor(random(allowedLetters.length));
		let rlet = allowedLetters.charAt(rlidx);
		if (!kboard.fadeLetters.includes(rlet)) {
			if (currentLetters[activeIndex] != rlet) {
				if (!testLetter(rlet)) {
					foundLetter = true;
					letter = rlet;
				}

			}
		}
	}
	if (foundLetter) {
		kboard.fadeKeyWrong(letter);
	}
}

function testLetter(whichLetter) {
	let wordTest = "";
	for (let i = 0; i < activeIndex; i++) {
		wordTest += currentLetters[i];
	}
	wordTest += whichLetter;
	for (let i = activeIndex + 1; i < lettersWord; i++) {
		wordTest += currentLetters[i];
	}
	if (validWords.includes(wordTest)) {
		return true;
	}
	return false;
}

function getCurrentWord() {
	let completeWord = "";
	for (let i = 0; i < lettersWord; i++) {
		completeWord += currentLetters[i];
	}
	if (lettersWord == 5) {
		completeWord = completeWord.toLowerCase();
	}
	return completeWord;
}

function checkCurrentWord(completeWord) {

	//console.log(completeWord);
	if (validWords.includes(completeWord)) {
		return true;
	} else {
		return false;
	}
}

function checkPossibility() {
	//see if any letter can solve current challenge
	let wordTest = "";
	for (let i = 0; i < activeIndex; i++) {
		wordTest += currentLetters[i];
	}
	let lastLetters = "";
	for (let i = activeIndex + 1; i < lettersWord; i++) {
		lastLetters += currentLetters[i];
	}
	let currentActiveLetter = currentLetters[activeIndex];
	for (let l = 0; l < allowedLetters.length; l++) {
		let testlet = allowedLetters.charAt(l);
		if (testlet != currentActiveLetter) {
			let testString = wordTest;
			testString += testlet;
			testString += lastLetters;
			if (validWords.includes(testString)) {
				//console.log(testString);
				lastSolution = testString;
				return true;
			}
		}
	}
	return false;
}




class LetterHolder {
	constructor(inLetter) {
		this.letter = inLetter;
		this.bgcol = 'lightblue';
		this.activeInput = false;
		this.flasher = 0;
		this.redFlash = 0;
		this.letterMorpher = null;
		this.targetLetter = null;
		this.morphStep = 0;
	}

	setLetterMorphTo(inTargetLetter) {
		this.targetLetter = inTargetLetter;
		this.letterMorpher = new LetterTween(this.letter, this.targetLetter, morphSteps);
		this.morphStep = 0;
	}

	renderAt(offsetx, offsety) {
		fill(this.bgcol);
		rect(offsetx, offsety, lblockw, lblockh, 10);


		if (this.activeInput) {
			let flashcol;
			if (this.redFlash > 0) {
				this.redFlash--;
				flashcol = color(255, 0, 0, 100);
				fill(flashcol);
				rect(offsetx, offsety, lblockw, lblockh, 10);
			} else {
				this.flasher += 0.05;
				let fval = abs(sin(this.flasher));
				let brt = fval * 255;
				flashcol = color(255, 255, 255, brt);
				fill(flashcol);
				let ttm = turnTimer / timeLimit;
				let flasshh = ttm * lblockh;
				rect(offsetx, offsety + flasshh, lblockw, lblockh - flasshh, 10);
			}


		}
		if (useLetterMorph && this.letterMorpher != null) {

			push();
			translate(offsetx + (lblockw * 0.5), offsety + lblockh - 60);
			let tv = this.morphStep / morphSteps;
			this.letterMorpher.fullRender(color(0, 0, 0), this.bgcol, tv);
			pop();
			this.morphStep++;
			if (this.morphStep == morphSteps) {
				//done morphing
				this.letter = this.targetLetter;
				this.letterMorpher = null;
			}

		} else {
			fill('black');
			textSize(180);
			textAlign(CENTER)
			textStyle(BOLD);
			text(this.letter, offsetx + (lblockw * 0.5), offsety + lblockh - 60);
		}

	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
